setup.src/options.ts:
export interface PaginationOptions {
  readonly maxItems: number;
  readonly cursor?: string;
}

setup.src/paginate.ts:
import type { PaginationOptions } from "./options";

export const paginate = <T>(items: ReadonlyArray<T>, options: PaginationOptions): ReadonlyArray<T> =>
  items.slice(0, options.maxItems);

setup.src/client.ts:
import { paginate } from "./paginate";

export const fetchPage = (items: ReadonlyArray<string>, maxItems = 10) =>
  paginate(items, { maxItems });

setup.test/paginate.test.ts:
import { expect, test } from "bun:test";
import { fetchPage } from "../src/client";
import { paginate } from "../src/paginate";

test("paginate slices to limit", () => {
  expect(paginate([1, 2, 3], { maxItems: 2 })).toEqual([1, 2]);
  expect(fetchPage(["a", "b", "c"], 1)).toEqual(["a"]);
});

